import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.DGvnA5EY.js";const n="/workbuddy-guide/assets/01-life-assistant.BX4txHpa.png",b=JSON.parse('{"title":"第 14 章 生活助手的价值，是减少琐碎","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 工作之外，生活里有一大堆\\"不起眼但费神\\"的小事：查攻略、拟一段话、算个账、记个 提醒。WorkBuddy 当生活助理，价值不在\\"多厉害\\"，而在把琐碎接住，让你把注意力 留给重要的事。它擅长\\"给方案\\"…","frontmatter":{"title":"第 14 章 生活助手的价值，是减少琐碎"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 生活助手的价值，是减少琐碎/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 生活助手的价值，是减少琐碎/index.md","lastUpdated":1791615980000}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 生活助手的价值，是减少琐碎/index.md"};function o(i,t,r,h,p,c){return e(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="第-14-章-生活助手的价值-是减少琐碎" tabindex="-1">第 14 章 生活助手的价值，是减少琐碎 <a class="header-anchor" href="#第-14-章-生活助手的价值-是减少琐碎" aria-label="Permalink to &quot;第 14 章 生活助手的价值，是减少琐碎&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>工作之外，生活里有一大堆&quot;不起眼但费神&quot;的小事：查攻略、拟一段话、算个账、记个 提醒。WorkBuddy 当生活助理，价值不在&quot;多厉害&quot;，而在<strong>把琐碎接住</strong>，让你把注意力 留给重要的事。它擅长&quot;给方案&quot;，不擅长&quot;替你负责&quot;——这一章教你把它用对位置。</p><p><img src="'+n+`" alt="一只小黑举着一张写满待办的小纸条，另一只手把琐事一件件摁进一个收纳盒" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;生活助手&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次要它帮什么" tabindex="-1">一、先想清楚：这次要它帮什么 <a class="header-anchor" href="#一、先想清楚-这次要它帮什么" aria-label="Permalink to &quot;一、先想清楚：这次要它帮什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>解决哪件琐事</td><td>规划周末杭州两日游，轻松不赶</td></tr><tr><td>受众</td><td>谁用这个方案</td><td>我和伴侣，带老人</td></tr><tr><td>材料</td><td>你已有的偏好/约束</td><td>预算 2000、不爱排队、住西湖边</td></tr><tr><td>格式</td><td>要清单、行程表还是一段话</td><td>按天的时间表 + 备选</td></tr><tr><td>验收</td><td>怎么判断可用</td><td>时间衔接合理、预算不超、有备选</td></tr></tbody></table><h2 id="二、先选对-skill-生活助手的组合" tabindex="-1">二、先选对 Skill：生活助手的组合 <a class="header-anchor" href="#二、先选对-skill-生活助手的组合" aria-label="Permalink to &quot;二、先选对 Skill：生活助手的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>通用 Agent（对话/参谋）</strong></td><td>攻略、拟稿、算账、比价</td><td>随叫随答，给选项和理由</td><td>决策权在你</td></tr><tr><td><strong>日历 / 提醒连接器</strong></td><td>提醒、待办真正生效</td><td>接上系统日历/待办后，提醒才落地</td><td>接法见第一篇第 7 章</td></tr><tr><td><strong>腾讯文档 / kdocs</strong></td><td>把清单、心愿单存成可共享</td><td>旅行清单、购物清单和家人同步</td><td>需授权</td></tr><tr><td><strong>find-skills</strong></td><td>找更专业的技能</td><td>&quot;有没有记账/菜谱技能&quot;</td><td>零成本入口</td></tr></tbody></table><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-出行攻略-带约束" tabindex="-1">提示词 1｜出行攻略（带约束） <a class="header-anchor" href="#提示词-1-出行攻略-带约束" aria-label="Permalink to &quot;提示词 1｜出行攻略（带约束）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我规划【杭州】两日游，时间【本周末】，同行【我和伴侣+一位老人】。</span></span>
<span class="line"><span>约束：总预算约 2000 元、不爱排队、住宿想在西湖边、节奏轻松不赶。</span></span>
<span class="line"><span>输出按天的时间表：时间段、去哪、吃什么、交通方式、预计花费，并给每个时段一个备选方案。</span></span></code></pre></div><h3 id="提示词-2-拟一段不好开口的话" tabindex="-1">提示词 2｜拟一段不好开口的话 <a class="header-anchor" href="#提示词-2-拟一段不好开口的话" aria-label="Permalink to &quot;提示词 2｜拟一段不好开口的话&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一条微信，委婉拒绝朋友这周末的饭局，理由是最近加班走不开，</span></span>
<span class="line"><span>但表达下周末再约的诚意。语气轻松、不刻意、30 字以内。</span></span></code></pre></div><h3 id="提示词-3-礼物参谋" tabindex="-1">提示词 3｜礼物参谋 <a class="header-anchor" href="#提示词-3-礼物参谋" aria-label="Permalink to &quot;提示词 3｜礼物参谋&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想给妈妈挑生日礼物，预算 300 内，她喜欢园艺和喝茶。</span></span>
<span class="line"><span>给我 5 个选项，每个选项写清：是什么、大概价格、为什么适合她、哪里能买。</span></span>
<span class="line"><span>最后告诉我如果只能选一个，你推荐哪个及理由。</span></span></code></pre></div><h3 id="提示词-4-算账-多人" tabindex="-1">提示词 4｜算账（多人） <a class="header-anchor" href="#提示词-4-算账-多人" aria-label="Permalink to &quot;提示词 4｜算账（多人）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三人 AA 聚餐，总计 386 元，其中 A 多付了饮料 28 元。</span></span>
<span class="line"><span>请算清楚：每人应付多少、A 实际多付了多少、其他两人该补给 A 多少。</span></span></code></pre></div><h2 id="四、执行步骤表" tabindex="-1">四、执行步骤表 <a class="header-anchor" href="#四、执行步骤表" aria-label="Permalink to &quot;四、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>给约束，出方案/选项</td><td>方案是否符合你的真实情况</td></tr><tr><td>2</td><td>你选，它细化</td><td>细节（价格/时间）是否靠谱</td></tr><tr><td>3</td><td>存清单/设提醒（接连接器后）</td><td>提醒是否真落地</td></tr></tbody></table><h2 id="五、和生活助手相处的分寸" tabindex="-1">五、和生活助手相处的分寸 <a class="header-anchor" href="#五、和生活助手相处的分寸" aria-label="Permalink to &quot;五、和生活助手相处的分寸&quot;">​</a></h2><p><strong>参谋 vs 裁判</strong>：它给选项和依据（参谋），最终决定权在你（裁判）。涉及人际关系、 花钱、健康的事，把它当参考，别当裁判——尤其是健康建议，以专业人士为准。</p><h2 id="六、零成本-skill-把常用参谋固化" tabindex="-1">六、零成本 Skill：把常用参谋固化 <a class="header-anchor" href="#六、零成本-skill-把常用参谋固化" aria-label="Permalink to &quot;六、零成本 Skill：把常用参谋固化&quot;">​</a></h2><p>跑顺提示词 3（礼物参谋）这类反复用的，用 <code>skill-creator</code> 固化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个&quot;送礼参谋&quot;技能：输入对象、关系、预算、喜好，输出 5 个带价格和理由的选项</span></span>
<span class="line"><span>并给首选推荐。触发词：送什么、礼物参谋。</span></span></code></pre></div><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：你拿到一份能照走的方案、一段能直接发的文字、一笔算清的账。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 方案/文字/数字符合你的约束（预算、语气、算法对得上）</li><li>[ ] 涉及健康/重大花钱的决定，你保留了最终判断</li><li>[ ] 隐私信息（地址/身份证/家人）没有写进任务里</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>生活助理</strong>：把 AI 用在个人日常琐事上，帮你规划、拟稿、计算、提醒。</p><p><strong>参谋 vs 裁判</strong>：AI 给选项和依据（参谋），最终决定权在你（裁判）。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把反复用的参谋类需求固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 用提示词 1 规划一次你真要去的短途，并核对预算</li><li>[ ] 让它拟一条你最近要发的、不好开口的消息</li><li>[ ] （进阶）用 skill-creator 把&quot;送礼参谋&quot;固化成技能</li><li>[ ] 梳理一遍：哪些隐私信息以后不写进任务里</li></ul><hr><p><em>下一篇：第 15 章——资讯整合，把信息流变成每日通知。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,37)])])}const k=a(l,[["render",o]]);export{b as __pageData,k as default};
